INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salman_al-ghamdi-swe326', 'stk-salman_al-ghamdi', 'SWE 326', 'doc', '{"docs": [{"id": "stk-dr-f98303", "n": "Dr. Sajjad Mahmood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "192-SWE326\nالتقييم للجزء الحضوري فقط\n\nالتحضير : ما كان يحضر أبدا، بس كان كلاسه 8 الصبح (هو يحب ذا الوقت في اغلب مواده)\nطريقة الشرح : يفتح سلايدات ويسولف، اقول يسولف لأنه ما يلتزم بالسلايدات بالضبط، يعطيك من خبرته وتجاربه والحاجات اللي يعرفها ومرتبطة بموضوع الكورس\nالكويزات : سهلة وصعبة؟ اظن عامل الوقت هو اللي مش قادر يزبطه للأسف، اسئلته تقدر تحلها وتجاوب عليها لكن الوقت ما يساعد ابد\nالمياجر: مياجره كتابية مرة، فيه صح وخطأ بس توقع انك بتكتب كثير، لكن سهلة وبتجيب درجة لو مذاكر\nالفاينلات : -\nالقريد النهائي: A، غالبا كنت بعطيه A+ لو كان في مادة ثانية زي 215 ولا 205.\nالصوت: واضح جدا وبلهجة كويسة\nإضافات : الدكتور متعاون جدا وحبيب ووسيع صدر، يقبل اي سؤال ويقبل اي سؤال واستفسار ومستعد ياخذ ويعطي معك عشان توصل لك المعلومة بأحسن شكل. للأسف حضرت نص ترم عنده قبل ما يقلب الوضع الاونلاين فما ادري صراحة كيفه في الاونلاين لأن الوضع كان حوسة مرة، لكنه دكتور ممتاز عموما", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526043-swe326", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sajjad-mahmood/98303/15", "user": "Salman_Al-Ghamdi", "ts": 1601882793000, "tid": 98303, "pn": 15}}]}', 1601882793000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-swe326', 'stk-tryagain', 'SWE 326', 'doc', '{"docs": [{"id": "stk-dr-f99239", "n": "Dr. Jameleddine Hassine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "SWE 326 - Software Testing and QA\n\nبنود التقييم :\n\nالتحضير :\nيحضر بورقة بداية الكلاس ويسجل المتأخرين\n\nطريقة الشرح :\nبطلة … الدكتور يشرح الموجود بالسلايدات ( طابع المادة في البداية حفظ ) وبعدها لما بدأ التطبيق صار يشرح أمثلة على السبورة والهومووركات ممتازة وتركز على الـ concept.\n\nالكويزات :\nسهلة جداً جداً … مذاكرة سريعة تضمن لك درجة كاملة\n\nالمياجر:\nالميجر الأول كان سهل جداً ( لأن الماتيريال كانت سهلة ) والأفرج كان مرتفع … الميجر الثاني كان شامل وجاب أغلب الافكار فإذا كنت فاهمها رح تقدر تحلها بسهولة …\n\nالفاينلات :\nأشوفه كان متوسط مائل للسهولة ويتأخر شوي الدكتور في التصحيح\n\nالقريد النهائي: a+\n\nالصوت: مرتفع\n\nإضافات :\n- الدكتور جداً محترم والتعامل معاه بطل.\n- البروجكت كان سهل جداً\n- أنصحك تنزل عنده ويكون خيارك الأول في أي مادة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492608-swe326", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameleddine-hassine/99239/3", "user": "TryAgain", "ts": 1526569108000, "tid": 99239, "pn": 3}}]}', 1526569108000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-akira-swe326', 'stk-akira', 'SWE 326', 'doc', '{"docs": [{"id": "stk-dr-f99239", "n": "Dr. Jameleddine Hassine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "SWE326-191\n\nالتحضير :\nيحضر في بداية الكلاس بالكمبيوتر, ولما وصلنا لنصف الترم وقف ما يحضر.\n\nطريقة الشرح :\nمن سلايدات ويشرحها بالتفصيل على السبورة.\n\nالكويزات :\nفي البداية تكون سهلة لانها تعتمد على الحفظ, بس بعدين تصعب خصوصا في الRIP model يعني يبيلك كومبايلر في مخك عشان تحلها.\n\nالمياجر:\nميدترم, 60% منه يعتمد عالحفظ, و 40% يعتمد عالفهم, اصعب شي فيه كان الRIP بعد.\n\nالفاينلات :\nالفاينل بعد كان صعب والافرج 17/35, كان شامل نص المنهج.\n\nالقريد النهائي:\nB\n\nالصوت:\nواضح و مرتفع\n\nإضافات :\nالدكتور محترم لأبعد درجة, وشرحه بطل ويعيد لك النقطة اكثر من مرة اذا مافهمت, بس عيبه الوحيد اختباراته صعبة نوعا ما, البروجكت كان سهل جدا 20% في الجيب, وفيه عرض بوربوينت عليه 5% سهل جدا بعد, الدكتور يحترم الوقت ومتواجد في الساعات المكتبية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518630-swe326", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameleddine-hassine/99239/4", "user": "Akira", "ts": 1577936804000, "tid": 99239, "pn": 4}}]}', 1577936804000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-swe326', 'stk-mohammed_mag', 'SWE 326', 'doc', '{"docs": [{"id": "stk-dr-f99239", "n": "Dr. Jameleddine Hassine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "SWE 326 - Lecture\n\nالتحضير : يوميا بدايه الكلاس ينادي الاسامي ويحضر، ويحضر بعد اخر الكلاس حق المتأخرين، وبعض الاحيان مايحضر.\n\nطريقة الشرح : شرحه جدا جميل، بعض الاحيان يتكلم عن التستنق بالواقع دامه خبير في هذا المجال، يحاول يوضح المعلومه يرسمها على السبوره .\n\nالكويزات : اختبرنا على 4 او 5 ماذكر، حذف اسوأ واحد وكانو سهلين وماتريال خفيف بشكل عام .\n\nالصوت : واضح و أكسنت مفهوم .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536731-swe326", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameleddine-hassine/99239/8", "user": "Mohammed_Mag", "ts": 1685667189000, "tid": 99239, "pn": 8}}]}', 1685667189000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
